"use strict";(globalThis.webpackChunkdialai_website=globalThis.webpackChunkdialai_website||[]).push([[8398],{5952(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/dialai/docs/intro","label":"Introduction to DIAL","docId":"intro","unlisted":false},{"type":"category","label":"Concepts","collapsed":false,"items":[{"type":"link","href":"/dialai/docs/concepts/intro","label":"Core Concepts","docId":"concepts/intro","unlisted":false},{"type":"link","href":"/dialai/docs/concepts/sessions","label":"Sessions","docId":"concepts/sessions","unlisted":false},{"type":"link","href":"/dialai/docs/concepts/specialists","label":"Specialists","docId":"concepts/specialists","unlisted":false},{"type":"link","href":"/dialai/docs/concepts/decision-cycle","label":"Decision Cycle","docId":"concepts/decision-cycle","unlisted":false},{"type":"link","href":"/dialai/docs/concepts/arbitration","label":"Arbitration","docId":"concepts/arbitration","unlisted":false},{"type":"link","href":"/dialai/docs/concepts/human-primacy","label":"Human Primacy","docId":"concepts/human-primacy","unlisted":false},{"type":"link","href":"/dialai/docs/concepts/related-work","label":"Related Work","docId":"concepts/related-work","unlisted":false}],"collapsible":true},{"type":"category","label":"Implementation","collapsed":false,"items":[{"type":"category","label":"Getting Started","items":[{"type":"link","href":"/dialai/docs/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/dialai/docs/getting-started/quick-start","label":"Quick Start","docId":"getting-started/quick-start","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Guides","items":[{"type":"link","href":"/dialai/docs/guides/state-machines","label":"State Machines","docId":"guides/state-machines","unlisted":false},{"type":"link","href":"/dialai/docs/guides/registering-specialists","label":"Registering Specialists","docId":"guides/registering-specialists","unlisted":false},{"type":"link","href":"/dialai/docs/guides/implementing-strategies","label":"Implementing Strategies","docId":"guides/implementing-strategies","unlisted":false},{"type":"link","href":"/dialai/docs/guides/proxy-mode","label":"Proxy Mode","docId":"guides/proxy-mode","unlisted":false},{"type":"link","href":"/dialai/docs/guides/progressive-collapse","label":"Progressive Collapse","docId":"guides/progressive-collapse","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"API Reference","items":[{"type":"link","href":"/dialai/docs/api/intro","label":"API Reference","docId":"api/intro","unlisted":false},{"type":"link","href":"/dialai/docs/api/types","label":"Types Reference","docId":"api/types","unlisted":false},{"type":"link","href":"/dialai/docs/api/submitArbitration","label":"submitArbitration(opts): Promise<ArbitrationResult>","docId":"api/submitArbitration","unlisted":false},{"type":"link","href":"/dialai/docs/api/cli","label":"CLI Reference","docId":"api/cli","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Examples","items":[{"type":"link","href":"/dialai/docs/examples/intro","label":"Examples","docId":"examples/intro","unlisted":false}],"collapsed":true,"collapsible":true}],"collapsible":true},{"type":"link","href":"/dialai/docs/agent-experience","label":"AI Agent Experience","docId":"agent-experience","unlisted":false},{"type":"link","href":"/dialai/docs/ecosystem","label":"Ecosystem","docId":"ecosystem","unlisted":false},{"type":"link","href":"/dialai/docs/roadmap","label":"Roadmap","docId":"roadmap","unlisted":false}]},"docs":{"agent-experience":{"id":"agent-experience","title":"AI Agent Experience","description":"DIAL is designed for LLM-driven agents to participate as proposers in decision cycles, to design state machines that encode governance workflows, and to develop custom applications that embed DIAL. This page explains how DIAL is optimized for agents and provides guidance for AI assistants working with the framework.","sidebar":"tutorialSidebar"},"api/cli":{"id":"api/cli","title":"CLI Reference","description":"The dialai command-line interface runs state machines to completion.","sidebar":"tutorialSidebar"},"api/createSession":{"id":"api/createSession","title":"createSession(machine: MachineDefinition, metaJson?: Record<string, unknown>): Promise<Session>","description":"Creates a new session instance from a machine definition. Generates a UUID, sets currentState to machine.initialState, and stores the session."},"api/evaluateConsensus":{"id":"api/evaluateConsensus","title":"evaluateConsensus(sessionId): Promise<ConsensusResult>","description":"Evaluates whether consensus has been reached for a session without executing any transition. This is a read-only operation that checks the current state of proposals."},"api/executeTransition":{"id":"api/executeTransition","title":"executeTransition(sessionId, transitionName, toState, reasoning?): Promise<Session>","description":"Executes a state transition on a session. Validates the transition is valid from the current state, records it in history, updates currentState, and clears all proposals for the session."},"api/getSession":{"id":"api/getSession","title":"getSession(sessionId: string): Promise<Session>","description":"Retrieves a session by its ID. Returns the full session object including current state, history, and machine definition."},"api/getSessions":{"id":"api/getSessions","title":"getSessions(): Promise<Session[]>","description":"Returns all stored sessions. Useful for listing active sessions or debugging."},"api/intro":{"id":"api/intro","title":"API Reference","description":"The dialai library provides functions for creating sessions, registering specialists, and managing the decision cycle. For the conceptual foundation, see Concepts.","sidebar":"tutorialSidebar"},"api/registerArbiter":{"id":"api/registerArbiter","title":"registerArbiter(opts): Promise<Arbiter>","description":"Registers an arbiter specialist for a machine. Arbiters evaluate consensus among proposals and determine winning transitions."},"api/registerProposer":{"id":"api/registerProposer","title":"registerProposer(opts): Promise<Proposer>","description":"Registers a proposer specialist for a machine. Proposers submit state transition proposals during the decision cycle."},"api/runSession":{"id":"api/runSession","title":"runSession(machine: MachineDefinition): Promise<Session>","description":"Runs a machine to completion. Creates a session, registers specialists (from the machine definition or a built-in deterministic proposer), and loops through the decision cycle until currentState === goalState."},"api/submitArbitration":{"id":"api/submitArbitration","title":"submitArbitration(opts): Promise<ArbitrationResult>","description":"Evaluates consensus and optionally executes the winning transition. Follows the same unified pattern as submitProposal: if the key decision parameter is omitted, the arbiter\'s strategy is invoked.","sidebar":"tutorialSidebar"},"api/types":{"id":"api/types","title":"Types Reference","description":"Complete type definitions for the dialai library. All types are exported from the main package.","sidebar":"tutorialSidebar"},"concepts/arbitration":{"id":"concepts/arbitration","title":"Arbitration","description":"The arbiter is the orchestrator of every decision cycle. It solicits proposals from specialists, scores endorsements per transition using alignment-weighted margins, and declares consensus when one transition\'s margin exceeds the configured threshold.","sidebar":"tutorialSidebar"},"concepts/consensus-strategies":{"id":"concepts/consensus-strategies","title":"Consensus Strategies","description":"DIAL\'s consensus mechanism is alignment margin \u2014 an alignment-weighted margin approach where each proposal acts as an endorsement of its transition, weighted by the proposer\'s alignment score. Consensus is reached when one transition\'s alignment-weighted margin exceeds the configured threshold. DIAL also ships with firstProposal as a convenience strategy for testing and single-proposer setups."},"concepts/decision-cycle":{"id":"concepts/decision-cycle","title":"Decision Cycle","description":"When a session is not in its goal state, the arbiter drives a decision cycle that orchestrates specialists to find consensus on the next transition.","sidebar":"tutorialSidebar"},"concepts/human-primacy":{"id":"concepts/human-primacy","title":"Human Primacy","description":"Humans have context that AI cannot access. Human decisions are the best available ground truth for calibrating AI specialists.","sidebar":"tutorialSidebar"},"concepts/intro":{"id":"concepts/intro","title":"Core Concepts","description":"DIAL orchestrates specialists \u2014 both AI and human \u2014 that compete and collaborate to navigate state machines through decision cycles. An arbiter drives each cycle, grouping proposals by transition and declaring consensus when one transition\'s alignment-weighted margin exceeds the threshold.","sidebar":"tutorialSidebar"},"concepts/related-work":{"id":"concepts/related-work","title":"Related Work","description":"DIAL solves a different problem than most AI frameworks. Understanding the distinction helps clarify what DIAL does.","sidebar":"tutorialSidebar"},"concepts/sessions":{"id":"concepts/sessions","title":"Sessions","description":"A session is an instance of a state machine that specialists navigate through decision cycles.","sidebar":"tutorialSidebar"},"concepts/specialists":{"id":"concepts/specialists","title":"Specialists","description":"Specialists are the pluggable actors that participate in sessions. They can be AI models, webhooks, local functions, or humans.","sidebar":"tutorialSidebar"},"ecosystem":{"id":"ecosystem","title":"Ecosystem","description":"DIAL measures whether AI specialists can reliably replicate human decisions, then progressively delegates when alignment is demonstrated. Several open-source projects share overlapping goals. This page lists the 10 closest.","sidebar":"tutorialSidebar"},"examples/intro":{"id":"examples/intro","title":"Examples","description":"This section contains example implementations demonstrating dialai library usage. For the concepts behind these examples, see Concepts.","sidebar":"tutorialSidebar"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"Get the dialai library up and running in your project. This section covers the practical implementation of DIAL\u2014for the concepts and theory, see Concepts.","sidebar":"tutorialSidebar"},"getting-started/quick-start":{"id":"getting-started/quick-start","title":"Quick Start","description":"Build your first DIAL state machine with specialists. This guide focuses on the code\u2014for the concepts behind what you\'re building, see Concepts.","sidebar":"tutorialSidebar"},"guides/implementing-strategies":{"id":"guides/implementing-strategies","title":"Implementing Strategies","description":"This guide covers how to implement strategy functions for specialists. For the conceptual foundation, see Specialists and Decision Cycle.","sidebar":"tutorialSidebar"},"guides/progressive-collapse":{"id":"guides/progressive-collapse","title":"Progressive Collapse","description":"This guide walks through the complete journey from cold start to collapsed execution \u2014 the exact algorithms, worked examples, and cost data at every stage. For the high-level overview, see the Core Concepts.","sidebar":"tutorialSidebar"},"guides/proxy-mode":{"id":"guides/proxy-mode","title":"Proxy Mode","description":"This guide covers distributed deployment patterns for the dialai library. DIAL supports running as an HTTP server or forwarding requests to a remote DIAL instance, enabling centralized state machine execution.","sidebar":"tutorialSidebar"},"guides/registering-specialists":{"id":"guides/registering-specialists","title":"Registering Specialists","description":"This guide covers how to register specialists using the dialai library. For the conceptual foundation, see Specialists.","sidebar":"tutorialSidebar"},"guides/SKILLS":{"id":"guides/SKILLS","title":"DIAL Skills Reference","description":"Complete skill reference for AI agents using DIAL"},"guides/skills/add-specialists/SKILL":{"id":"guides/skills/add-specialists/SKILL","title":"Add Specialists","description":"Add AI or human specialists to a DIAL machine. Use when configuring proposers."},"guides/skills/create-machine/SKILL":{"id":"guides/skills/create-machine/SKILL","title":"Create a Machine Definition","description":"Create a DIAL state machine definition. Use when defining a new decision process as JSON."},"guides/skills/decision-cycles/SKILL":{"id":"guides/skills/decision-cycles/SKILL","title":"Decision Cycles","description":"Understand DIAL decision cycles. Use when learning how Propose, Arbitrate, Execute works."},"guides/skills/index":{"id":"guides/skills/index","title":"Agent Skills","description":"Modular skills for AI agents using DIAL"},"guides/skills/mcp-server/SKILL":{"id":"guides/skills/mcp-server/SKILL","title":"MCP Server Mode","description":"Run DIAL as an MCP server for AI assistants. Use when integrating with Claude Desktop or other MCP clients."},"guides/skills/programmatic-usage/SKILL":{"id":"guides/skills/programmatic-usage/SKILL","title":"Programmatic Usage","description":"Use DIAL programmatically in TypeScript/JavaScript. Use when integrating DIAL into your own code."},"guides/skills/run-machine/SKILL":{"id":"guides/skills/run-machine/SKILL","title":"Run a DIAL State Machine","description":"Run a DIAL state machine from the CLI. Use when executing a machine definition JSON file."},"guides/skills/troubleshooting/SKILL":{"id":"guides/skills/troubleshooting/SKILL","title":"Troubleshooting","description":"Debug common DIAL issues. Use when something goes wrong during execution."},"guides/state-machines":{"id":"guides/state-machines","title":"State Machines","description":"This guide covers how to define state machines in the dialai library. For the conceptual foundation, see Sessions.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction to DIAL","description":"DIAL (Dynamic Integration between AI and Labor) is a task-oriented coordination framework for AI and human specialists making decisions together within state machines.","sidebar":"tutorialSidebar"},"roadmap":{"id":"roadmap","title":"Roadmap","description":"This roadmap captures recommendations from research on making libraries easier for agents to use. Items are organized by their complexity-to-value tradeoff: high-value, low-complexity items first.","sidebar":"tutorialSidebar"}}}}')}}]);